python3 - <<'PY'
import json, os, struct, sys

konzept = json.load(open("ai-automation-frontend/src/data/walkthroughImagePrompts.json"))
ids = list(konzept["szenen"])
want_bg = konzept.get("hintergrund", "#1b1714").lstrip("#")
want_bg = tuple(int(want_bg[i:i+2], 16) for i in (0, 2, 4))
outdir = "ai-automation-frontend/public/walkthrough"

def png_size(path):
    """Masse aus dem IHDR-Chunk — ohne Pillow, damit die harte Pruefung ueberall laeuft."""
    with open(path, "rb") as fh:
        head = fh.read(24)
    if head[:8] != b"\x89PNG\r\n\x1a\n":
        return None
    return struct.unpack(">II", head[16:24])

try:
    from PIL import Image
    pillow = True
except ImportError:
    pillow = False
    print("HINWEIS: Pillow fehlt — Randfarbe und Farbverteilung werden nicht gemessen.")

hart, weich, ok_ids = [], [], []
verteilungen = {}

for pid in ids:
    path = os.path.join(outdir, pid + ".png")
    if not os.path.exists(path):
        hart.append(f"{pid}: keine Datei"); continue
    size = os.path.getsize(path)
    if size < 30_000:
        hart.append(f"{pid}: nur {size} Bytes — vermutlich Fehlschlag"); continue
    if size > 900_000:
        weich.append(f"{pid}: {size//1024} KB, gross fuer ein Panel")
    dim = png_size(path)
    if dim is None:
        hart.append(f"{pid}: keine PNG-Datei"); continue
    if dim != (640, 640):
        hart.append(f"{pid}: {dim[0]}x{dim[1]} statt 640x640 — Normierung fehlgeschlagen"); continue

    if pillow:
        im = Image.open(path).convert("RGB")
        w, h = im.size
        rand = [im.getpixel(p) for p in
                ((2, 2), (w-3, 2), (2, h-3), (w-3, h-3), (w//2, 2), (w//2, h-3), (2, h//2), (w-3, h//2))]
        mittel = tuple(sum(c[i] for c in rand) // len(rand) for i in range(3))
        abstand = max(abs(mittel[i] - want_bg[i]) for i in range(3))
        if abstand > 24:
            weich.append(f"{pid}: Rand {'#%02x%02x%02x' % mittel} statt {'#%02x%02x%02x' % want_bg} (Abstand {abstand})")
        klein = im.resize((64, 64))
        verteilungen[pid] = [sum(v) for v in zip(*[klein.getpixel((x, y)) for x in range(64) for y in range(64)])]

    ok_ids.append(pid)
    print(f"OK   {pid}: {dim[0]}x{dim[1]}, {size//1024} KB")

# Ausreisser im Farbklima: was aus dem Satz faellt, ist fast immer Stildrift.
if len(verteilungen) >= 3:
    mittelwert = [sum(v[i] for v in verteilungen.values()) / len(verteilungen) for i in range(3)]
    for pid, v in verteilungen.items():
        rel = max(abs(v[i] - mittelwert[i]) / max(mittelwert[i], 1) for i in range(3))
        if rel > 0.22:
            weich.append(f"{pid}: Farbklima weicht {rel*100:.0f} % vom Satz ab")

print()
for zeile in weich: print("WARNUNG", zeile)
for zeile in hart: print("FEHLER ", zeile)
print()
print(f"{len(ok_ids)}/{len(ids)} Bilder bestehen die harte Pruefung")
if hart:
    sys.exit(1)
